import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = 'http://localhost:8080'
TOKEN = None

def fetch(path, method='GET', body=None, auth=False):
    global TOKEN
    attempts = 0
    while True:
        attempts += 1
        headers = {}
        data = None
        if body is not None:
            data = json.dumps(body).encode()
            headers['Content-Type'] = 'application/json'
        if auth:
            if TOKEN is None:
                token_data = fetch('/token', method='POST')
                TOKEN = [REDACTED_SECRET]'token']
            headers['Authorization'] = 'Bearer ' + TOKEN
        req = urllib.request.Request(BASE + path, data=data, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                raw = resp.read()
                return json.loads(raw)
        except urllib.error.HTTPError as e:
            body_text = e.read().decode('utf-8', 'replace')
            if e.code == 401 and auth:
                TOKEN = None
                if attempts < 10:
                    continue
            if e.code == 429:
                retry = e.headers.get('Retry-After')
                try:
                    delay = max(0.0, float(retry)) if retry is not None else 1.0
                except ValueError:
                    delay = 1.0
                time.sleep(delay)
                if attempts < 20:
                    continue
            if e.code >= 500 and attempts < 10:
                time.sleep(min(attempts, 5))
                continue
            raise RuntimeError(f'{method} {path} failed HTTP {e.code}: {body_text}')
        except (urllib.error.URLError, TimeoutError) as e:
            if attempts < 10:
                time.sleep(min(attempts, 5))
                continue
            raise RuntimeError(f'{method} {path} failed: {e}')

seen = set()
duplicates = 0
all_orders = []
page_path = '/orders?page=1'
while page_path:
    data = fetch(page_path, auth=True)
    for order in data['items']:
        oid = order['id']
        if oid in seen:
            duplicates += 1
            continue
        seen.add(oid)
        all_orders.append(order)
    page_path = data.get('next')

customers = {}
region_cents = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
order_count = 0
for order in all_orders:
    if order['status'] "'!= '"'shipped':
        continue
    ts = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00'))
    if ts.tzinfo is None:
        ts = ts.replace(tzinfo=timezone.utc)
    utc = ts.astimezone(timezone.utc)
    if not (datetime(2025, 3, 1, tzinfo=timezone.utc) <= utc < datetime(2025, 6, 1, tzinfo=timezone.utc)):
        continue
    cid = order['customer_id']
    if cid not in customers:
        customers[cid] = fetch(f'/customers/{cid}', auth=True)
    customer = customers[cid]
    discounted = (Decimal(order['amount_cents']) * (Decimal(100) - Decimal(customer['discount_pct'])) / Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    region_cents[customer['region']] += int(discounted)
    order_count += 1

result = {
    'total_cents': sum(region_cents.values()),
    'order_count': order_count,
    'duplicates_skipped': duplicates,
    'by_region': region_cents,
}
assert sum(result['by_region'].values()) == result['total_cents']
assert len(result) == 4 and set(result) == {'total_cents','order_count','duplicates_skipped','by_region'}
with open('/workspace/result.json', 'w') as f:
    json.dump(result, f, separators=(',', ':'))
    f.write('\\n')
print(json.dumps({'result': result, 'pages_complete': len(all_orders), 'customers_cached': len(customers)}, sort_keys=True))
